-- CP6 CHECK (phase 1m, card B13 step T1): every row must be true
select 'ledger, shared list and ownership history exist with forced RLS' as what, (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='cp' and c.relname in ('tenant_ledger','shared_domain','domain_ownership') and c.relrowsecurity and c.relforcerowsecurity)=3 as ok
union all select 'no table right for cp_lookup or PUBLIC on the three tables', not has_table_privilege('cp_lookup','cp.domain_ownership','select') and not has_table_privilege('cp_lookup','cp.shared_domain','select') and not has_table_privilege('public','cp.tenant_ledger','select')
union all select 'every CP6 function is SECURITY DEFINER with fixed search_path', (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='cp' and p.proname in ('tenant_note','domain_ownership_sync','tenant_of_domain','tenant_registry_check','tenant_ledger_verify') and p.prosecdef and p.proconfig::text like '%search_path=pg_catalog, pg_temp%')=5
union all select 'cp_lookup can run tenant_of_domain and tenant_registry_check', has_function_privilege('cp_lookup','cp.tenant_of_domain(text, timestamptz)','execute') and has_function_privilege('cp_lookup','cp.tenant_registry_check()','execute')
union all select 'cp_lookup can NEVER run the sync, PUBLIC runs nothing', not has_function_privilege('cp_lookup','cp.domain_ownership_sync()','execute') and not has_function_privilege('public','cp.tenant_of_domain(text, timestamptz)','execute') and not has_function_privilege('public','cp.domain_ownership_sync()','execute')
union all select 'one domain cannot belong to two tenants at once (EXCLUDE or open-period unique index)', exists (select 1 from pg_constraint where conname='domain_ownership_no_overlap') or exists (select 1 from pg_indexes where indexname='domain_ownership_one_open')
union all select 'the guard triggers are there (ownership 2, ledger 3, shared 2)', (select count(*) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='cp' and not t.tgisinternal and ((c.relname='domain_ownership') or (c.relname='tenant_ledger') or (c.relname='shared_domain')))=7
union all select 'the shared list holds the well-known free providers and gmail.com never resolves', exists (select 1 from cp.shared_domain where domain='gmail.com') and cp.tenant_of_domain('gmail.com') is null
union all select 'no overlapping ownership periods', (cp.tenant_registry_check()->>'overlapping_periods')::int = 0
union all select 'every verified domain of a tenant has an open history period', (cp.tenant_registry_check()->>'verified_missing_history')::int = 0
union all select 'the ledger chain verifies', cp.tenant_ledger_verify()
union all select 'earlier phases are untouched (CP5 doors still closed for PUBLIC)', to_regprocedure('cp.consent_push(uuid,text,text,text,text)') is null or not has_function_privilege('public','cp.consent_push(uuid,text,text,text,text)','execute')
union all select 'FACT (not a pass/fail): '||cp.tenant_registry_check()::text, true;
